def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def db_physical_state(db: Path) -> str:
    h = hashlib.sha256()
    for suffix in ("", "-wal"):
        p = Path(str(db) + suffix)
        h.update(suffix.encode("utf-8"))
        if not p.exists():
            h.update(b"MISSING")
            continue
        h.update(str(p.stat().st_size).encode("ascii"))
        h.update(sha256_file(p).encode("ascii"))
    return h.hexdigest()


def atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(path.name + ".v43_tmp")
    temp.write_bytes(data)
    os.replace(temp, path)


def fail(message: str) -> None:
    print("\n" + "=" * 100)
    print("DỪNG AN TOÀN - BÀI SÁP NHẬP V4.3")
    print(message)
    print("Bộ cài không thực hiện sáp nhập và không chủ động ghi phocap.db.")
    print("=" * 100)
    raise SystemExit(1)


def find_project_root() -> Path:
    here = Path(__file__).resolve().parent
    candidates = [here, Path.cwd(), here.parent]
    if os.name == "nt":
        candidates.append(Path(r"C:\PhoCap"))
    seen = set()
    for c in candidates:
        try:
            c = c.resolve()
        except Exception:
            continue
        if str(c) in seen:
            continue
        seen.add(str(c))
        if (c / "app").is_dir() and (c / "data" / "phocap.db").is_file():
            return c
    fail("Không xác định được thư mục dự án. Hãy chép file cài vào C:\\PhoCap và chạy lại từ C:\\PhoCap.")
    raise AssertionError


def sqlite_readonly_check(db: Path) -> tuple[str, int]:
    uri = db.resolve().as_uri() + "?mode=ro"
    con = sqlite3.connect(uri, uri=True, timeout=30)
    try:
        integrity = str(con.execute("PRAGMA integrity_check").fetchone()[0])
        fk_count = len(con.execute("PRAGMA foreign_key_check").fetchall())
        return integrity, fk_count
    finally:
        con.close()


def current_state_ok(root: Path) -> tuple[bool, list[str]]:
    notes = []
    all_final = True
    for rel, final_hash in PATCHED_HASHES.items():
        p = root / rel
        if not p.exists():
            all_final = False
            if rel in EXPECTED_OLD:
                notes.append(f"THIẾU FILE CŨ: {rel}")
            continue
        got = sha256_file(p)
        if got != final_hash:
            all_final = False
        notes.append(f"{rel}: {got}")
    return all_final, notes


def validate_inputs(root: Path) -> None:
    # Dependency lõi phải đúng trạng thái V2/V4.1 đã kiểm thử.
    for rel, expected in DEPENDENCY_HASHES.items():
        p = root / rel
        if not p.exists():
            fail(f"Thiếu dependency bắt buộc: {rel}")
        got = sha256_file(p)
        if got != expected:
            fail(
                f"Dependency {rel} đã khác bản V4.1 được kiểm thử.\n"
                f"Hash hiện tại: {got}\nHash cần: {expected}\n"
                "Không tự ghi đè để tránh làm mất thay đổi khác."
            )

    # File V4.1 có thể đang ở trạng thái cũ hoặc đã là V4.3 (cài lại/idempotent).
    for rel, old_hash in EXPECTED_OLD.items():
        p = root / rel
        if not p.exists():
            fail(f"Thiếu file nền V4.1: {rel}")
        got = sha256_file(p)
        if got not in {old_hash, PATCHED_HASHES[rel]}:
            fail(
                f"File {rel} không còn đúng V4.1 và cũng chưa phải V4.3.\n"
                f"Hash hiện tại: {got}\n"
                "Có thể file đã được sửa sau V4.2; V4.3 sẽ không tự ghi đè."
            )

    # File mới: chỉ chấp nhận chưa tồn tại hoặc đúng byte V4.3.
    for rel in PATCHED_HASHES:
        if rel in EXPECTED_OLD:
            continue
        p = root / rel
        if p.exists() and sha256_file(p) != PATCHED_HASHES[rel]:
            fail(f"File mới {rel} đã tồn tại nhưng nội dung khác V4.3; dừng để tránh ghi đè.")


def restore_backup(root: Path, backup_dir: Path, original_exists: dict[str, bool]) -> None:
    for rel in PATCHED_HASHES:
        dst = root / rel
        src = backup_dir / rel
        if original_exists.get(rel):
            if src.exists():
                dst.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src, dst)
        else:
            try:
                if dst.exists():
                    dst.unlink()
            except Exception:
                pass


def smoke_audit(root: Path) -> dict:
    code = r'''
import json
from app.services.school_merger_source_audit_service import source_registry_summary, audit_official_plans
from app.services.school_merger_preview_service import build_official_plan_impact_preview
s = source_registry_summary()
out = {"registry": s, "levels": {}}
for level in ("TH", "MN", "THCS"):
    a = audit_official_plans(level_code=level)
    out["levels"][level] = {"total": a["total"], "pass": a["pass_count"], "block": a["block_count"]}
for pid, key in (("PA2026-D9C894490094", "nghi_thuy_to_nghi_tan"), ("PA2026-38D91045ABB4", "nghi_thu_to_thu_thuy")):
    try:
        p = build_official_plan_impact_preview(pid)
        out[key] = {
            "v43_source_check_ok": bool(p.get("v43_source_check_ok")),
            "v41_state_check_ok": bool(p.get("v41_state_check_ok")),
            "simulation_ok": bool(p.get("simulation_ok")),
            "safe": bool(p.get("safe_for_future_execution")),
            "blockers": p.get("blockers") or [],
            "schools": [
                {
                    "role": x.get("role"), "school": x.get("school_name"), "status": x.get("status"),
                    "source_active": x.get("source_active_rows"), "db_eligible": x.get("active_db_eligible"),
                    "issues": x.get("issues") or [],
                }
                for x in ((p.get("source_audit") or {}).get("school_checks") or [])
            ],
        }
    except Exception as exc:
        out[key] = {"error": str(exc)}
print(json.dumps(out, ensure_ascii=True, default=str))
'''
    env = dict(os.environ)
    env["PYTHONPATH"] = str(root) + (os.pathsep + env["PYTHONPATH"] if env.get("PYTHONPATH") else "")
    # Windows: khi Python con ghi vào PIPE, sys.stdout có thể rơi về cp1252 dù terminal cha hiển thị UTF-8.
    # Ép UTF-8 + JSON ASCII-safe để smoke audit không chết vì tiếng Việt.
    env["PYTHONIOENCODING"] = "utf-8"
    env["PYTHONUTF8"] = "1"
    proc = subprocess.run(
        [sys.executable, "-c", code], cwd=str(root), env=env,
        capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=120,
    )
    if proc.returncode != 0:
        raise RuntimeError("Smoke audit V4.3 lỗi:\n" + (proc.stderr or proc.stdout or "Không có thông tin lỗi"))
    lines = [x for x in proc.stdout.splitlines() if x.strip()]
    if not lines:
        raise RuntimeError("Smoke audit V4.3 không trả dữ liệu.")
    return json.loads(lines[-1])


def main() -> None:
    root = find_project_root()
    db = root / "data" / "phocap.db"
    print("=" * 100)
    print("BÀI SÁP NHẬP V4.3.1 - SỬA UNICODE SMOKE AUDIT / GIỮ NGUYÊN CỔNG V4.3")
    print("Dự án:", root)
    print("Database:", db)
    print("=" * 100)

    validate_inputs(root)
    integrity_before, fk_before = sqlite_readonly_check(db)
    if integrity_before.lower() != "ok" or fk_before:
        fail(f"Database chưa an toàn trước cài: integrity={integrity_before}; foreign_key={fk_before}")
    db_state_before = db_physical_state(db)

    all_final, _ = current_state_ok(root)
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    report_root = root / "exports" / "Bai_Sap_Nhap_V4_3_Kiem_Tra_Nguon_Toan_Tinh"
    report_root.mkdir(parents=True, exist_ok=True)

    backup_dir = root / "backups" / f"backup_truoc_cai_v4_3_{timestamp}"
    original_exists: dict[str, bool] = {}
    changed_files: list[str] = []

    try:
        if not all_final:
            for rel in PATCHED_HASHES:
                src = root / rel
                original_exists[rel] = src.exists()
                if src.exists():
                    dst = backup_dir / rel
                    dst.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(src, dst)

            for rel, b64 in EMBEDDED_FILES.items():
                dst = root / rel
                wanted = PATCHED_HASHES[rel]
                if dst.exists() and sha256_file(dst) == wanted:
                    continue
                atomic_write(dst, base64.b64decode(b64))
                if sha256_file(dst) != wanted:
                    raise RuntimeError(f"Hash sau ghi không đúng: {rel}")
                changed_files.append(rel)

            for rel in (
                "app/routers/school_merger.py",
                "app/services/school_merger_preview_service.py",
                "app/services/school_merger_execution_service.py",
                "app/services/school_merger_source_audit_service.py",
            ):
                py_compile.compile(str(root / rel), doraise=True)
        else:
            for rel in PATCHED_HASHES:
                original_exists[rel] = (root / rel).exists()

        # Xác nhận byte cuối cùng.
        for rel, wanted in PATCHED_HASHES.items():
            got = sha256_file(root / rel)
            if got != wanted:
                raise RuntimeError(f"Kiểm tra cuối thất bại {rel}: {got} != {wanted}")

        smoke = smoke_audit(root)
        integrity_after, fk_after = sqlite_readonly_check(db)
        db_state_after = db_physical_state(db)
        if integrity_after.lower() != "ok" or fk_after:
            raise RuntimeError(f"Database hậu kiểm không đạt: integrity={integrity_after}; foreign_key={fk_after}")
        if db_state_after != db_state_before:
            raise RuntimeError(
                "Phát hiện phocap.db/WAL thay đổi trong lúc cài V4.3. "
                "Bộ cài không chủ động ghi DB; hãy dừng Uvicorn/người dùng khác rồi kiểm tra lại."
            )

    except Exception as exc:
        if backup_dir.exists():
            restore_backup(root, backup_dir, original_exists)
        fail("Cài V4.3 không hoàn tất; mã nguồn đã được khôi phục nếu đã chạm file.\nLỗi: " + str(exc))

    report = {
        "lesson": "BÀI SÁP NHẬP V4.3.1 - SỬA UNICODE SMOKE AUDIT / GIỮ NGUYÊN CỔNG V4.3",
        "installed_at": datetime.now().isoformat(timespec="seconds"),
        "project_root": str(root),
        "status": "ALREADY_INSTALLED" if all_final else "INSTALLED",
        "changed_files": changed_files,
        "backup_dir": str(backup_dir) if backup_dir.exists() else "",
        "database": {
            "integrity_before": integrity_before, "fk_before": fk_before,
            "integrity_after": integrity_after, "fk_after": fk_after,
            "physical_state_unchanged": db_state_after == db_state_before,
        },
        "source_registry": smoke.get("registry"),
        "province_audit": smoke.get("levels"),
        "cua_lo_checks": {
            "nghi_thuy_to_nghi_tan": smoke.get("nghi_thuy_to_nghi_tan"),
            "nghi_thu_to_thu_thuy": smoke.get("nghi_thu_to_thu_thuy"),
        },
        "rules": [
            "Mọi phương án MAPPED phải PASS nguồn V4.3 trước khi mô phỏng/thực hiện.",
            "Kiểm tra cả trường nguồn và trường đích.",
            "Nguồn được khóa theo cấp học + năm liền trước + xã/phường + trường.",
            "Mã nhân sự/nhân thân/vị trí hồ sơ năm nguồn phải khớp; xung đột là BLOCK.",
            "Fingerprint nguồn được tính lại bên trong BEGIN IMMEDIATE trước khi ghi.",
            "Thiếu file nguồn đúng cấp/năm = BLOCK, không suy đoán.",
        ],
    }
    report_path = report_root / f"bao_cao_v4_3_{timestamp}.json"
    report_path.write_text(json.dumps(report, ensure_ascii=False, indent=2, default=str), encoding="utf-8")

    print("\n" + "=" * 100)
    print("BÀI SÁP NHẬP V4.3.1 - CÀI ĐẶT THÀNH CÔNG" if not all_final else "BÀI SÁP NHẬP V4.3.1 - V4.3 ĐÃ CÀI, KIỂM TRA LẠI THÀNH CÔNG")
    print("Database: KHÔNG THAY ĐỔI")
    print(f"Registry nguồn: {smoke.get('registry', {}).get('dataset_count', 0)} bộ dữ liệu; {smoke.get('registry', {}).get('school_roster_count', 0)} trường có nguồn.")
    for level in ("TH", "MN", "THCS"):
        x = (smoke.get("levels") or {}).get(level) or {}
        print(f"{level}: tổng {x.get('total', 0)} phương án cần kiểm tra; PASS {x.get('pass', 0)}; BLOCK {x.get('block', 0)}")
    print("Báo cáo:", report_path)
    if backup_dir.exists():
        print("Backup mã nguồn trước cài:", backup_dir)
    print("\nLƯU Ý: V4.3 hiện có nguồn Tiểu học 2025-2026. MN/THCS bị khóa an toàn cho tới khi bổ sung nguồn đúng cấp/năm.")
    print("=" * 100)


if __name__ == "__main__":
    main()
